#include <bits/stdc++.h>
using namespace std;

int main() {
    // 6 位数以内；下界取 100，1 虽然也满足定义但不在答案范围内
    const int LIMIT = 59049 * 6;
    for (int x = 100; x <= LIMIT; x++) {
        int t = x, sum = 0;
        while (t) {
            int d = t % 10;
            sum += d * d * d * d * d;
            t /= 10;
        }
        if (sum == x) cout << x << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 高精度：按 10 进制低位在前存位
vector<int> mul(vector<int> a, int b) {
    vector<int> res(a.size(), 0);
    long long carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        long long cur = (long long)a[i] * b + carry;
        res[i] = cur % 10;
        carry = cur / 10;
    }
    while (carry) { res.push_back(carry % 10); carry /= 10; }
    return res;
}

int main() {
    string n;
    int k;
    cin >> n >> k;
    vector<pair<int, int>> rules(k);
    for (auto &r : rules) cin >> r.first >> r.second;

    bool can[10];
    for (int d = 0; d < 10; d++) can[d] = true;      // 0 次变换

    for (int round = 0; round < 10; round++) {        // 规则可级联，反复松弛
        bool changed = false;
        for (auto &r : rules) {
            if (can[r.first] && !can[r.second]) {
                can[r.second] = true;
                changed = true;
            }
        }
        if (!changed) break;
    }

    int cnt = 0;
    for (int d = 0; d < 10; d++) if (can[d]) cnt++;

    vector<int> ans(1, 1);
    for (char ch : n) ans = mul(ans, cnt);

    for (int i = (int)ans.size() - 1; i >= 0; i--) cout << ans[i];
    cout << "\n";
    return 0;
}
